/**
 * Build the mapping context for per-lens copy/Markdown from the project:
 * character mapping info is extracted from each card's single
 * 性格/外貌备注 (labelled 造型：/音色：/语气基调： segments and
 * classifiable clauses — the card has no separate mapping fields).
 * v4.03：场景设置已删除——场景映射只用剧本每段自带的场景名
 * （sceneName），不再有项目级场景描述 / 场景图参与。
 * v4.83 套用补写修复：场景资产卡（project.sceneAssets，AI解剖套用
 * 与「按分镜写资产提示词」都会建）正式接入映射上下文——此前这里
 * 恒传 scenes: []，场景卡里的描述与生图提示词写进了库却从没喂进
 * 分镜页场景映射，映射永远只能写「未填写」（用户截图实报的根因）。
 * 现在按卡名对场景名供描述 + 生图提示词 + 资产状态；道具映射从
 * 剧本自带的 propAssets（套用写入）取，逐镜头按名过滤。
 */
function buildMappingContext(
  project: ProjectDetail,
  script?: ScriptData | null,
): LensMappingContext {
  return {
    characters: project.characters.map((c) => ({
      name: c.name,
      role: c.role,
      note: c.note,
      // v5.21 锁人①③：稳定 characterId 与资产图地址一并进映射上
      // 下文——镜头包附图清单按 characterId 点名、有无资产图按
      // imageUrl 判定。此前上下文只有 name/role/note，类型上就堵
      // 死了图片流入分镜链路。
      id: c.id,
      imageUrl: c.imageUrl,
    })),
    scenes: project.sceneAssets.map((s) => ({
      name: s.name,
      description: s.description,
      asset: s.imageUrl ? "场景资产图（已生成）" : "场景资产图",
      promptZh: s.promptZh,
    })),
    props: (script?.propAssets ?? []).map((p) => ({
      name: p.name,
      description: p.description,
      promptZh: p.promptZh,
    })),
    textSceneDescription: undefined,
  };
}

type ProjectDetail = NonNullable<
  ApiResponse<typeof api, "getProject">["project"]
>;
/** Server-side validation result (shared rules, computed by the server). */
type ValidateResult = ApiResponse<typeof api, "validateScript">;
type Character = ProjectDetail["characters"][number];

/**
 * Every window/workbench switch lands back at the top of the main window
 * area. The page itself is fixed (100dvh, no page scroll); only the main
 * window area scrolls, so "back to top" scrolls that container.
 */
function scrollToPageTop() {
  const main = document.getElementById("main-scroll");
  if (main) {
    main.scrollTo({ top: 0, left: 0, behavior: "auto" });
    return;
  }
  try {
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  } catch {
    window.scrollTo(0, 0);
  }
}

